css:
/* General body styling */
body {
    font-family: Arial, sans-serif;
    font-size: 12px;
    color: #333;
    margin: 20px;
}

/* Header */
h3, h4 {
    color: #1a73e8;
    margin: 0 0 10px 0;
}

h3 {
    text-align: center;
}

/* Labels and values */
label {
    font-weight: bold;
    display: inline-block;
    width: 120px;
}

p {
    margin: 5px 0;
}

/* Table styling */
table {
    width: 100%;
    border-collapse: collapse;
    margin-top: 10px;
}

table th, table td {
    border: 1px solid #ddd;
    padding: 6px 8px;
    text-align: left;
    vertical-align: top;
}

table th {
    background-color: #f2f2f2;
    color: #333;
}

table tr:nth-child(even) {
    background-color: #fafafa;
}

/* Footer / notes */
.footer {
    margin-top: 20px;
    font-size: 11px;
    color: #555;
}

/* Highlight totals */
.total-row td {
    font-weight: bold;
    background-color: #eaeaea;
}
